INSERT INTO `system_settings` (`id`, `setting_key`, `setting_value`, `setting_type`, `description`, `created_at`, `updated_at`) VALUES ('27', 'about_story_title', 'Welcome to Alondes Dorm', 'text', 'About story section title', '2026-07-15 17:11:27', '2026-07-15 17:11:27');
INSERT INTO `system_settings` (`id`, `setting_key`, `setting_value`, `setting_type`, `description`, `created_at`, `updated_at`) VALUES ('28', 'about_story_text', 'Founded with the vision of providing safe, comfortable, and affordable accommodation for students, Alondes Dorm has been a trusted home for hundreds of students pursuing their academic dreams.||We understand the challenges students face when looking for the right place to stay while studying. That&amp;amp;amp;#039;s why we&amp;amp;amp;#039;ve created a community-oriented living space that feels like home.', 'text', 'About story text (use || for paragraphs)', '2026-07-15 17:11:27', '2026-07-19 20:05:21');
INSERT INTO `system_settings` (`id`, `setting_key`, `setting_value`, `setting_type`, `description`, `created_at`, `updated_at`) VALUES ('29', 'about_years_label', '15+ Years', 'text', 'Years badge label', '2026-07-15 17:11:27', '2026-07-19 19:34:45');
